// Gate on a shared secret, then flatten the payload into one line of text.
//
// The webhook path is public: anything on the internet can POST to it. This
// header check is what stops strangers pushing messages into your Telegram.
// Replace the placeholder with a long random string, e.g.
//   openssl rand -hex 32
// and keep the same value in whatever service calls this webhook.
const EXPECTED_TOKEN = 'replace-me-openssl-rand-hex-32';

const request = $input.first().json;
const headers = request.headers || {};
// Header names arrive lower-cased.
const presented = headers['x-alert-token'];

if (EXPECTED_TOKEN === 'replace-me-openssl-rand-hex-32') {
  throw new Error('Set EXPECTED_TOKEN in this node before activating the workflow.');
}

if (presented !== EXPECTED_TOKEN) {
  throw new Error('Unauthorised: missing or wrong X-Alert-Token header');
}

const body = request.body || {};

const level = String(body.level || 'info').toUpperCase();
const icon = { INFO: 'i', WARN: '!', ERROR: 'X' }[level] || 'i';
const source = String(body.source || 'unknown');
const message = typeof body.message === 'string'
  ? body.message
  : JSON.stringify(body);

// Plain text on purpose: no parse_mode, so a stray * or _ in an alert can't
// make Telegram reject the whole message.
const text = [
  `[${icon}] ${level} - ${source}`,
  message,
  `at ${new Date().toISOString()}`,
].join('\n');

return [{ json: { text, level, source } }];
